import { environment } from '../services/environment';
import { gameConfig } from '../models/config-model';
import { queryStringParams } from '../services/query-string';
import { IEndpoints } from '../types';
import { device } from '../services/device';

export function getEndpoints(): IEndpoints {
    const sites = {
        arcade: {
            debug: 'https://dev-www.tombolaarcade.co.uk',
            dev: 'https://dev-www.tombolaarcade.co.uk',
            stage: 'https://stage-www.tombolaarcade.co.uk',
            live: 'https://www.tombolaarcade.co.uk'
        },
        bingo: {
            debug: 'https://dev.tombola.co.uk',
            dev: 'https://dev.tombola.co.uk',
            stage: 'https://stage.tombola.co.uk',
            live: 'https://www.tombola.co.uk'
        }
    };
    const launchedFrom = queryStringParams.launchedFrom as 'arcade' | 'bingo' ?? 'arcade';
    const activeSite = sites[launchedFrom] ?? sites.arcade;

    /**
     * Defaults unknown engines to bubble to get a valid response for UserData and various errors like TimeKeeper.
     * Though it will overwrite the GameMessage and GameSettings info with dummy data from the GameModel and GameSettings defined in the game project
     */
    const engineName = gameConfig.engineName === 'unknown' ? 'bubble' : gameConfig.engineName;
    const recentWinnersApi = 'content/v3/recentwinners?gameName=';
    const chatUrl = 'chat/index.html';
    const gameLaunchApi = launchedFrom === 'arcade' ?
        'arcade-games/playgame?gameName=' :
        'bingo-games/play/';

    return {
        urls: {
            debug: {
                api: `${activeSite.debug}/api/`,
                cdnRoot: 'https://dev-cdn.tombolaarcade.co.uk/clients/mobile/arcade/assets/en_GB/',
                cdnTranslationsRoot: 'https://dev-cdn.tombolaarcade.co.uk/clients/mobile/arcade/translations/',
                cdnGameName: `${gameConfig.cdnFolderName}/`,
                game: `https://dev-games.tombolaarcade.co.uk/${engineName}/`,
                platform: `${activeSite.debug}/`,
                recentWinners: `${sites.arcade.debug}/api/${recentWinnersApi}`,
                myAccount: `${activeSite.debug}/my-account`,
                sharedFonts: 'sharedFonts/fonts-v2.css',
                chat: 'http://localhost:9002/',
                chatHelp: `${activeSite.debug}/bingo-chat-community`,
                gameInGame: 'https://dev-desktop.tombolaarcade.co.uk',
                deepLink: `${activeSite.debug}/${gameLaunchApi}`
            },
            dev: {
                api: `${activeSite.dev}/api/`,
                cdnRoot: 'https://dev-cdn.tombolaarcade.co.uk/clients/mobile/arcade/assets/en_GB/',
                cdnTranslationsRoot: 'https://dev-cdn.tombolaarcade.co.uk/clients/mobile/arcade/translations/',
                cdnGameName: `${gameConfig.cdnFolderName}/`,
                game: `https://dev-games.tombolaarcade.co.uk/${engineName}/`,
                platform: `${activeSite.dev}/`,
                recentWinners: `${sites.arcade.dev}/api/${recentWinnersApi}`,
                myAccount: `${activeSite.dev}/my-account`,
                sharedFonts: 'sharedFonts/fonts-v2.css',
                chat: `https://dev-client.tombola.co.uk/${chatUrl}`,
                chatHelp: `${activeSite.dev}/bingo-chat-community`,
                gameInGame: 'https://dev-desktop.tombolaarcade.co.uk',
                deepLink: `${activeSite.dev}/${gameLaunchApi}`
            },
            stage: {
                api: `${activeSite.stage}/api/`,
                cdnRoot: 'https://stage-cdn.tombolaarcade.co.uk/clients/mobile/arcade/assets/en_GB/',
                cdnTranslationsRoot: 'https://stage-cdn.tombolaarcade.co.uk/clients/mobile/arcade/translations/',
                cdnGameName: `${gameConfig.cdnFolderName}/`,
                game: `https://stage-games.tombolaarcade.co.uk/${engineName}/`,
                platform: `${activeSite.stage}/`,
                recentWinners: `${sites.arcade.stage}/api/${recentWinnersApi}`,
                myAccount: `${activeSite.stage}/my-account`,
                sharedFonts: 'sharedFonts/fonts-v2.css',
                chat: `https://stage-client.tombola.co.uk/${chatUrl}`,
                chatHelp: `${activeSite.stage}/bingo-chat-community`,
                gameInGame: 'https://stage-desktop.tombolaarcade.co.uk',
                deepLink: `${activeSite.stage}/${gameLaunchApi}`
            },
            live: {
                api: `${activeSite.live}/api/`,
                cdnRoot: 'https://cdn.tombolaarcade.co.uk/clients/mobile/arcade/assets/en_GB/',
                cdnTranslationsRoot: 'https://cdn.tombolaarcade.co.uk/clients/mobile/arcade/translations/',
                cdnGameName: `${gameConfig.cdnFolderName}/`,
                game: `https://games.tombolaarcade.co.uk/${gameConfig.engineName}/`,
                platform: `${activeSite.live}/`,
                recentWinners: `${sites.arcade.live}/api/${recentWinnersApi}`,
                myAccount: `${activeSite.live}/my-account`,
                sharedFonts: 'sharedFonts/fonts-v2.css',
                chat: `https://client.tombola.co.uk/${chatUrl}`,
                chatHelp: `${activeSite.live}/bingo-chat-community`,
                gameInGame: 'https://desktop.tombolaarcade.co.uk',
                deepLink: `${activeSite.live}/${gameLaunchApi}`
            }
        },
        actions: {
            TIME_KEEPER_ACKNOWLEDGEMENT: 'timekeeper/ack',
            REALITY_CHECK_ACKNOWLEDGEMENT: 'realitycheck/ack'
        },
        promoTandCs: 'promotions/terms-and-conditions',
        prizeLeagueTandCs: `${activeSite.live}/pages/prize-league-april-26`,
        deposit: device.type.isNative ? 'ADD_CARD' : `${activeSite[environment]}/payment/add-funds`,
        verifyDetails: `${activeSite[environment]}/verification/step1`,
        gameLaunchers: 'game-discovery/game-launcher/default',
        demoGameLaunchers: 'game-discovery/v1/demo-game-launcher/default',
        RESUME: 'resume',
        BEGIN: 'begin',
        CONTINUE: 'continue'
    };
}
